"""ENG owns the shared NWW London agreement. Native hull limits, new lifecycle."""
from pathlib import Path
from hoi4_script import read, one, values, parse, dump, quoted

ROOT=Path(__file__).resolve().parents[1]
GAME=Path('D:/Steam/steamapps/common/Hearts of Iron IV')
MEMBERS=['ENG','ITA','GER','FRA','JAP','CHI','USA']
IDEAS=['MTG_naval_treaty_adherent','MTG_naval_treaty_cheating','MTG_naval_treaty_adherent_reduced','MTG_naval_treaty_cheating_reduced']
P='ENG_london_'


def write(path,text):
    path=ROOT/path;path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text('# Owner: ENG. Shared London naval agreement; generated by tools/build_london_treaty.py.\n'+text.rstrip()+'\n',encoding='utf-8',newline='\n')


def main():
    locs={'russian':{},'english':{}}
    def loc(key,ru,en):
        locs['russian'][key]=ru;locs['english'][key]=en;return key
    def local(key,ru,en):return loc(P+key,ru,en)
    for idea in IDEAS:
        raised=idea.endswith('_reduced')
        title='Лондонское морское соглашение'+(' — защитная оговорка' if raised else '')
        english='London Naval Agreement'+(' — protective clause' if raised else '')
        caps='6000 / 12000 / 10500' if raised else '5300 / 10000 / 9500'
        if 'cheating' in idea:caps='6500 / 14000 / 10750' if raised else '5700 / 11500 / 10250'
        loc(idea,title,english)
        loc(idea+'_desc','Лондонский компромисс Британии, Италии, Германии, Франции, Японии, Китая и США сдерживает стоимость новых морских вооружений. Пределы стоимости проектов (крейсер / тяжёлый корабль / авианосец): '+caps+'. Существующий флот не подлежит автоматическому списанию.',
            'The London compromise between Britain, Italy, Germany, France, Japan, China and the United States limits the cost of new naval armaments. Design cost limits (cruiser / heavy ship / carrier): '+caps+'. Existing fleets are not automatically scrapped.')
    treaty='has_naval_treaty_trigger = yes'
    tags='OR = { '+' '.join('tag = '+t for t in MEMBERS)+' }'
    remove=' '.join('remove_ideas = '+i for i in IDEAS)
    category=local('category','Лондонское морское соглашение','The London Naval Agreement')
    local('category_desc','Участники при открытии сценария: Великобритания, Италия, Германия, Франция, Япония, Китай и США. Действующих подписантов: [?global.ENG_london_members|0]. Ограничения относятся к стоимости новых проектов кораблей, а не к числу уже построенных кораблей. Выход одной страны не исключает остальные.',
          'Opening signatories: Britain, Italy, Germany, France, Japan, China and the United States. Current signatories: [?global.ENG_london_members|0]. Limits apply to the production cost of new ship designs, not existing fleet size. One withdrawal does not expel the remaining members.')
    write('common/decisions/categories/ENG_naval_treaty_categories.txt',f'{category} = {{ icon = GFX_decision_category_MTG_naval_treaties picture = GFX_decision_cat_picture_naval_treaties allowed = {{ {tags} }} visible = {{ {treaty} NOT = {{ has_global_flag = {P}ended }} }} }}')
    effects=[]
    def effect(key,body):effects.append(P+key+' = {\n'+body+'\n}')
    recount='set_variable = { global.ENG_london_members = 0 } set_global_flag = { flag = MTG_naval_treaty_signatories value = 0 } '
    recount+='every_country = { if = { limit = { '+treaty+' } set_country_flag = ENG_london_was_member add_to_variable = { global.ENG_london_members = 1 } modify_global_flag = { flag = MTG_naval_treaty_signatories value = 1 } } else_if = { limit = { has_country_flag = ENG_london_was_member } clr_country_flag = ENG_london_was_member set_global_flag = ENG_london_withdrawal } }'
    effect('recount',recount)
    native_decisions=one(read(GAME/'common/decisions/MTG_naval_treaty.txt'),'MTG_naval_treaties')
    missions=[k for k,v,_ in native_decisions if one(v,'days_mission_timeout') is not None]
    cleanup=' '.join('remove_mission = '+k for k in missions)
    effect('dissolve',f'set_global_flag = {P}ended clr_global_flag = {P}conference_busy every_country = {{ limit = {{ {treaty} }} {remove} set_country_flag = MTG_naval_treaty_abandoned }} {P}recount = yes')
    setup=f'if = {{ limit = {{ NOT = {{ has_global_flag = {P}initialized }} }} set_global_flag = {P}initialized clr_global_flag = MTG_second_london_conference every_country = {{ {cleanup} if = {{ limit = {{ NOT = {{ {tags} }} }} {remove} }} }} '
    # New campaigns get their members from country history. An early existing
    # save may restore missing signatories once, never a country that withdrew.
    setup+='if = { limit = { date < 1937.1.1 NOT = { has_global_flag = ENG_london_ended } } '
    for t in MEMBERS:
        setup+=f'{t} = {{ if = {{ limit = {{ exists = yes NOT = {{ has_country_flag = MTG_naval_treaty_abandoned }} NOT = {{ {treaty} }} }} add_ideas = MTG_naval_treaty_adherent }} }} '
    setup+='} } '
    setup+=f'if = {{ limit = {{ NOT = {{ has_global_flag = {P}us_revision }} }} set_global_flag = {P}us_revision if = {{ limit = {{ date < 1937.1.1 NOT = {{ has_global_flag = {P}ended }} }} USA = {{ if = {{ limit = {{ exists = yes NOT = {{ has_country_flag = MTG_naval_treaty_abandoned }} NOT = {{ {treaty} }} }} add_ideas = MTG_naval_treaty_adherent }} }} }} }} '+P+'tick = yes'
    effect('setup',setup)
    tick=f'if = {{ limit = {{ has_global_flag = {P}ended }} every_country = {{ limit = {{ {treaty} }} {remove} set_country_flag = MTG_naval_treaty_abandoned }} }} '+P+'recount = yes '
    tick+=f'if = {{ limit = {{ NOT = {{ has_global_flag = {P}ended }} OR = {{ check_variable = {{ var = global.ENG_london_members value = 3 compare = less_than }} any_country = {{ {treaty} any_enemy_country = {{ {treaty} }} }} }} }} {P}dissolve = yes }}'
    effect('tick',tick)
    effect('withdraw',f'remove_naval_treaty_effect = yes set_global_flag = {P}withdrawal {P}tick = yes every_other_country = {{ limit = {{ {treaty} }} country_event = {{ id = nww_london.1 days = 1 }} }}')
    # The protective clause is part of the original agreement, not a unilateral
    # demand for disarmament or a free war goal against a refusing nonmember.
    upgrade=f'set_global_flag = {P}escalated clr_global_flag = {P}conference_busy '
    upgrade+='every_country = { limit = { '+treaty+' } if = { limit = { has_idea = MTG_naval_treaty_adherent } swap_ideas = { remove_idea = MTG_naval_treaty_adherent add_idea = MTG_naval_treaty_adherent_reduced } } else_if = { limit = { has_idea = MTG_naval_treaty_cheating } swap_ideas = { remove_idea = MTG_naval_treaty_cheating add_idea = MTG_naval_treaty_cheating_reduced } } country_event = { id = nww_london.2 days = 1 } }'
    effect('escalate',upgrade)
    write('common/scripted_effects/ENG_naval_treaty_effects.txt','\n\n'.join(effects))
    hooks=[f'on_startup = {{ effect = {{ ENG = {{ {P}setup = yes }} }} }}']
    for i,t in enumerate(MEMBERS):
        anchor=' '.join(prev+' = { exists = no }' for prev in MEMBERS[:i])
        hooks.append(f'on_daily_{t} = {{ effect = {{ if = {{ limit = {{ {anchor} }} {P}tick = yes }} }} }}')
    write('common/on_actions/ENG_naval_treaty_on_actions.txt','on_actions = {\n'+'\n'.join(hooks)+'\n}')
    withdraw=local('withdraw','Уведомить о выходе из соглашения','Give Notice of Withdrawal')
    local('withdraw_desc','75 политической власти, 35 дней. После истечения срока снимает наши ограничения. При отмене возвращает стоимость. Остальные подписанты сохраняют соглашение, пока их не станет меньше трёх или между ними не начнётся война.',
          '75 political power, 35 days. Removes our restrictions after notice expires. Cancellation refunds the cost. Remaining signatories retain the agreement until fewer than three remain or they go to war with one another.')
    clause=local('clause','Применить защитную оговорку','Invoke the Protective Clause')
    local('clause_desc','После выхода подписанта: 100 политической власти и 35 дней общей подготовки. Поднимает пределы стоимости проектов всем оставшимся участникам: крейсеры 5300 → 6000, тяжёлые корабли 10000 → 12000, авианосцы 9500 → 10500. Уже существующие корабли не уничтожаются.',
          'After a withdrawal: 100 political power and 35 days of shared preparation. Raises design cost limits for all remaining signatories: cruisers 5300 → 6000, heavy ships 10000 → 12000, carriers 9500 → 10500. Existing ships are not destroyed.')
    decisions=f'{category} = {{\n'
    decisions+=f'{withdraw} = {{ icon = generic_naval visible = {{ {treaty} }} available = {{ has_capitulated = no NOT = {{ has_global_flag = {P}conference_busy }} }} cost = 75 days_remove = 35 fire_only_once = yes remove_effect = {{ {P}withdraw = yes }} cancel_trigger = {{ OR = {{ NOT = {{ {treaty} }} has_global_flag = {P}ended }} }} cancel_effect = {{ add_political_power = 75 }} ai_will_do = {{ factor = 0 modifier = {{ add = 1 has_war = yes date > 1937.1.1 }} }} }}\n'
    decisions+=f'{clause} = {{ icon = generic_naval visible = {{ {treaty} has_global_flag = {P}withdrawal NOT = {{ has_global_flag = {P}escalated }} }} available = {{ has_capitulated = no NOT = {{ has_global_flag = {P}conference_busy }} }} cost = 100 days_remove = 35 fire_only_once = yes complete_effect = {{ set_global_flag = {P}conference_busy }} remove_effect = {{ {P}escalate = yes }} cancel_trigger = {{ OR = {{ NOT = {{ {treaty} }} has_global_flag = {P}ended has_global_flag = {P}escalated }} }} cancel_effect = {{ clr_global_flag = {P}conference_busy add_political_power = 100 }} ai_will_do = {{ factor = 2 }} }}\n}}'
    write('common/decisions/ENG_naval_treaty_decisions.txt',decisions)
    # Keep externally referenced IDs, without the old forced withdrawals,
    # China exception, fleet-ratio ultimatums or duplicate automated conferences.
    write('common/decisions/MTG_naval_treaty.txt','MTG_naval_treaties = {\n'+'\n'.join(k+' = { visible = { always = no } available = { always = no } }' for k,_,_ in native_decisions)+'\n}')
    native_events=read(GAME/'events/MTG_naval_treaty_events.txt')
    write('events/MTG_naval_treaty_events.txt','add_namespace = MTG_naval_treaty\n'+'\n'.join('country_event = { id = '+one(v,'id')+' hidden = yes is_triggered_only = yes immediate = { } }' for v in values(native_events,'country_event')))
    ev=['add_namespace = nww_london']
    for n,title,eng,desc,edesc in [
        (1,'Выход из Лондонского соглашения','Withdrawal from the London Agreement','[FROM.GetNameDef] завершает процедуру выхода. Оставшиеся участники сохраняют ограничения и могут воспользоваться заранее согласованной защитной оговоркой.','[FROM.GetNameDef] has completed the withdrawal procedure. Remaining parties retain the limits and may invoke the agreed protective clause.'),
        (2,'Защитная оговорка вступает в силу','The Protective Clause Takes Effect','Выход одного из участников изменил морской баланс. Для всех оставшихся подписантов действуют одинаковые повышенные пределы стоимости проектов.','A withdrawal has changed the naval balance. The same increased design cost limits now apply to every remaining signatory.')]:
        key='nww_london.'+str(n);loc(key+'.t',title,eng);loc(key+'.d',desc,edesc);loc(key+'.a','Принять к сведению','Take note')
        ev.append(f'country_event = {{ id = {key} title = {key}.t desc = {key}.d picture = GFX_report_event_naval_treaty is_triggered_only = yes option = {{ name = {key}.a }} }}')
    write('events/ENG_naval_treaty_events.txt','\n'.join(ev))
    # Remove vanilla treaty initialization recursively, including 1939 blocks.
    # Equipment, governments, alliances and all other history stay untouched.
    def clean(nodes):
        out=[]
        for k,v,o in nodes:
            if k in ['set_global_flag','modify_global_flag','clr_global_flag'] and (one(v,'flag') if isinstance(v,list) else v) in ['MTG_second_london_conference','MTG_naval_treaty_signatories']:continue
            if k in ['add_ideas','remove_ideas']:
                if isinstance(v,str) and v in IDEAS:continue
                if isinstance(v,list):v=[n for n in v if n[1] not in IDEAS]
            if isinstance(v,list):v=clean(v)
            out.append((k,v,o))
        return out
    for tag in MEMBERS:
        filename=next((ROOT/'history/countries').glob(tag+' - *.txt'),None)
        if filename is None:filename=next((GAME/'history/countries').glob(tag+' - *.txt'))
        nodes=clean(read(filename))
        if tag in MEMBERS:nodes+=parse('add_ideas = MTG_naval_treaty_adherent')
        write('history/countries/'+filename.name,dump(nodes))
    for lang,entries in locs.items():
        path=ROOT/f'localisation/{lang}/ENG_naval_treaty_l_{lang}.yml'
        path.write_text('l_'+lang+':\n'+'\n'.join(' '+k+':0 '+quoted(v) for k,v in entries.items())+'\n',encoding='utf-8-sig',newline='\n')
    print('Built London agreement: seven equal signatories including USA, native design caps, paid notice/protective clause, actual recount and war/collapse safeguards.')


if __name__=='__main__':main()
